package app.ledgedroid.core

import java.math.BigDecimal
import java.time.LocalDate

/**
 * Add auto postings to a (balanced) transaction, like hledger's modifyTransactions:
 *
 *  - rules are applied one after another, and each rule sees the postings added by earlier
 *    rules (so "= virtual_savings" can match a posting generated by "= income:wage")
 *  - a rule's postings are inserted right after each posting its query matches
 *  - a *N amount multiplies the matched posting's amount (only the commodities the rule's cur:
 *    terms select); if the *N amount has a commodity symbol, the result uses that commodity
 *  - a plain amount is added as written
 *  - "%account" in a rule's account name is replaced by the matched posting's account
 */
fun applyAutoRules(t: Transaction, rules: List<AutoRule>): Transaction {
    var postings = t.postings
    for (rule in rules) {
        val current = t.copy(postings = postings)
        val out = ArrayList<Posting>(postings.size + rule.postings.size)
        for (p in postings) {
            out.add(p)
            if (rule.query.matches(current, p)) rule.postings.mapTo(out) { generatePosting(rule, it, p) }
        }
        postings = out
    }
    return if (postings === t.postings) t else t.copy(postings = postings)
}

private fun generatePosting(rule: AutoRule, rp: RulePosting, matched: Posting): Posting {
    val account = if (rp.account.contains("%account")) rp.account.replace("%account", matched.account) else rp.account
    val written = rp.amount!!
    val amount = if (!rp.isMultiplier) written else {
        val m = matched.amount
        val q = if (rule.query.matchesCommodity(m.commodity)) m.quantity.multiply(written.quantity) else BigDecimal.ZERO
        if (written.commodity.isEmpty()) {
            // Keep the matched commodity; a total (@@) cost scales with the quantity, a unit cost doesn't.
            val cost = m.cost?.let { c -> if (c.isTotal) c.copy(quantity = c.quantity.multiply(written.quantity.abs())) else c }
            Amount(m.commodity, q, cost)
        } else {
            Amount(written.commodity, q, written.cost)
        }
    }
    return Posting(
        account = account, amount = amount, kind = rp.kind, status = rp.status,
        generated = true, line = rp.line,
    )
}

/** Back to the parser's form, for the final balancing pass. Every posting has an amount by now. */
internal fun Transaction.toRaw(): RawTransaction =
    RawTransaction(index, date, date2, status, code, description, comment, line).also { rt ->
        rt.lastLine = lastLine
        postings.mapTo(rt.postings) { p ->
            RawPosting(p.account, p.kind, p.status, p.amount, p.assertion, p.comment, p.line,
                inferred = p.inferred, generated = p.generated)
        }
    }

internal fun ruleRawTransaction(r: PeriodicRule, date: LocalDate, index: Int): RawTransaction =
    RawTransaction(index, date, null, r.status, "", r.description, "", r.line).also { t ->
        t.lastLine = r.lastLine
        r.postings.forEach { p -> t.postings.add(RawPosting(p.account, p.kind, p.status, p.amount, null, "", p.line)) }
    }

/** The balanced transactions periodic rules generate within [span] (hledger's runPeriodicTransaction). */
fun periodicTransactions(rules: List<PeriodicRule>, span: DateSpan, styles: Styles): List<Transaction> {
    val raw = ArrayList<RawTransaction>()
    for (r in rules) for (d in r.dates(span)) raw.add(ruleRawTransaction(r, d, raw.size))
    return balanceTransactions(raw, styles, emptyList(), checkAssertions = false).first
}
